# ===== Two things to check before trusting an `EQS` number =====

## ---- eqs-ratio-box ----
# split() orders groups alphabetically; the limit vectors are built by name and
# the assertion fails the render if they ever drift apart.
grp  <- split(seq_len(ncol(Re)), dplyr::case_when(
  grepl("_equity$", colnames(Re))     ~ "equity",
  grepl("_government$", colnames(Re)) ~ "government",
  grepl("_credit$", colnames(Re))     ~ "credit",
  TRUE                                ~ "commodity"))
gmin <- c(commodity = 0.00, credit = 0.05, equity = 0.20, government = 0.10)
gmax <- c(commodity = 0.15, credit = 0.40, equity = 0.60, government = 0.50)
stopifnot(identical(names(grp), names(gmin)), identical(names(grp), names(gmax)))

spec_eqs_ratio <- base_spec |>
  add.constraint(type = "box", min = 0, max = 0.25) |>
  add.constraint(type = "group", groups = grp,
                 group_min = unname(gmin), group_max = unname(gmax)) |>
  add.objective(type = "return", name = "mean") |>
  add.objective(type = "risk",   name = "EQS", arguments = list(p = 0.95))

o_eqs_ratio <- optimize.portfolio(Re, spec_eqs_ratio, optimize_method = "CVXR")  # EQSratio = TRUE
w_r     <- w_of(o_eqs_ratio)
group_w <- vapply(grp, function(g) sum(w_r[g]), numeric(1))

c(sum = sum(w_r), largest = max(w_r),
  box_binds    = all(w_r <= 0.25 + 1e-6),
  groups_bind  = all(group_w >= gmin - 1e-6 & group_w <= gmax + 1e-6),
  reported_EQS = as.numeric(extractObjectiveMeasures(o_eqs_ratio)$EQS),
  EQS_of_weights = extract_risk(Re, w_r)$EQS)

## ---- eqs-sign ----
# The empirical version of the minimization in @eq-10-ru for a nonnegative
# series v: the average of its largest alpha share, interpolated at the edge.
tail_mean <- function(v, alpha = 0.05) {
  v <- sort(v, decreasing = TRUE); m <- alpha * length(v); k <- floor(m)
  (sum(v[seq_len(k)]) + (m - k) * v[k + 1]) / m
}
r_es <- as.numeric(Re %*% w_es)
eqs_check <- c(package_EQS            = extract_risk(Re, w_es)$EQS,
               tail_of_squared_gains  = tail_mean(pmax(r_es, 0)^2),
               tail_of_squared_losses = tail_mean(pmax(-r_es, 0)^2),
               package_EQS_on_negated = extract_risk(-Re, w_es)$EQS)
stopifnot(all.equal(eqs_check[["package_EQS"]], eqs_check[["tail_of_squared_gains"]],
                    tolerance = 1e-3))
signif(eqs_check, 4)

skew_of <- function(w) as.numeric(skewness(as.numeric(Re %*% w)))
stopifnot(skew_of(w_eqs) < skew_of(w_es))        # the order the next sentence states

# ===== What each objective bought =====

## ---- four-portfolios ----
portfolios <- list(`minimum variance` = w_var,
                   `minimum ES` = w_es,
                   `quadratic utility, lambda = 2` = w_qu,
                   `minimum modified ES (search)` = w_mes)

measures_of <- function(w) {
  x  <- as.numeric(Re %*% w)                                       # excess, what was optimized
  xt <- xts::xts(as.numeric(R %*% w), order.by = zoo::index(R))    # total, for the wealth path
  c(US_credit = w[["US_credit"]], positions = sum(w > 0.005),
    ret = mean(x) * 12, vol = stats::sd(x) * sqrt(12),
    ES = loss_es(x),
    modified_ES = as.numeric(ES(x, p = 0.95, method = "modified", invert = FALSE)),
    utility = (mean(x) - 2 * stats::var(x)) * 12,                   # mu - lambda sigma^2, lambda = 2
    skewness = as.numeric(skewness(x)),
    max_drawdown = as.numeric(maxDrawdown(xt)))
}
four <- t(vapply(portfolios, measures_of, numeric(9))) |>
  as.data.frame() |>
  tibble::rownames_to_column("portfolio")

## ---- tbl-10-four ----
# The same problem under four risk measures. Volatility annualized; expected
# shortfall at 95%, monthly, historical and Cornish-Fisher; drawdown on the
# total-return wealth path.
four |>
  dplyr::transmute(portfolio,
                   US_credit = sprintf("%.1f%%", 100 * pmax(US_credit, 0)),   # a solver zero can be -1e-17
                   positions = sprintf("%.0f", positions),
                   vol = sprintf("%.2f%%", 100 * vol),
                   ES = sprintf("%.2f%%", 100 * ES),
                   modified_ES = sprintf("%.2f%%", 100 * modified_ES),
                   skewness = sprintf("%.2f", skewness),
                   max_drawdown = sprintf("%.1f%%", 100 * max_drawdown)) |>
  kable(align = "lrrrrrrr",
        col.names = c("", "US_credit", "positions", "volatility", "ES", "modified ES",
                      "skewness", "max drawdown"))

## ---- four-facts ----
f4 <- function(p, col) four[[col]][four$portfolio == p]
stopifnot(four$portfolio[which.min(four$vol)]     == "minimum variance",
          four$portfolio[which.min(four$ES)]      == "minimum ES",
          four$portfolio[which.max(four$utility)] == "quadratic utility, lambda = 2")
best_mes <- four$portfolio[which.min(four$modified_ES)]

# The orders and names the three paragraphs below state.
convex   <- four[four$portfolio != "minimum modified ES (search)", ]
held     <- function(w) names(w)[w > 0.005]
only_var <- setdiff(held(w_var), held(w_es))      # held by minimum variance alone
only_es  <- setdiff(held(w_es), held(w_var))      # held by minimum ES alone
n_agree  <- ncol(Re) - length(only_var) - length(only_es)
stopifnot(best_mes != "minimum modified ES (search)",
          four$portfolio[which.max(four$US_credit)] == "quadratic utility, lambda = 2",
          all(grepl("_equity$", setdiff(held(w_qu), "US_credit"))),
          convex$portfolio[which.max(convex$skewness)] == "minimum ES",
          names(which.max(w_var)) == "US_government", names(which.max(w_es)) == "US_government",
          length(only_var) == 1L, length(only_es) == 1L,
          skew_total[[only_var]] < 0, skew_total[[only_es]] > 0)

# ===== Each portfolio on every measure =====

## ---- tbl-10-cross ----
# Each portfolio on each objective. Bold marks the measure a row was chosen
# by; an asterisk marks the best value in a column. Volatility annualized,
# shortfalls monthly at 95%, utility the annualized certainty equivalent at
# lambda = 2.
cross <- four |>
  dplyr::select(portfolio, vol, ES, utility, modified_ES)
own <- c(`minimum variance` = "vol", `minimum ES` = "ES",
         `quadratic utility, lambda = 2` = "utility", `minimum modified ES (search)` = "modified_ES")
best <- c(vol = which.min(cross$vol), ES = which.min(cross$ES),
          utility = which.max(cross$utility), modified_ES = which.min(cross$modified_ES))
cell <- function(col, fmt) {
  v <- sprintf(fmt, 100 * cross[[col]])
  v <- ifelse(seq_len(nrow(cross)) == best[[col]], paste0(v, "*"), v)
  ifelse(own[cross$portfolio] == col, paste0("**", v, "**"), v)
}
tibble::tibble(portfolio = cross$portfolio,
               vol = cell("vol", "%.2f%%"), ES = cell("ES", "%.2f%%"),
               utility = cell("utility", "%.2f%%"), modified_ES = cell("modified_ES", "%.2f%%")) |>
  kable(align = "lrrrr",
        col.names = c("", "volatility", "ES", "utility", "modified ES"))

# ===== Out of sample, read from the register =====

## ---- oos ----
oos <- utils::read.csv("tables/oos-sweep.csv") |>
  dplyr::filter(universe == "classes", frequency == "months", basis == "gross",
                strategy %in% c("min_variance", "min_cvar")) |>
  dplyr::arrange(window, strategy)
stopifnot(nrow(oos) == 6L)
pick <- function(w, s, col) oos[[col]][oos$window == w & oos$strategy == s]

## ---- tbl-10-oos ----
# Minimum variance and minimum expected shortfall out of sample, monthly
# rebalancing, gross of costs, three estimation windows. Read from the
# register that chapter 25 computes.
oos |>
  dplyr::transmute(window, strategy = c(min_variance = "minimum variance",
                                        min_cvar = "minimum ES")[strategy],
                   sharpe = sprintf("%.3f", sharpe),
                   es_95 = sprintf("%.2f%%", 100 * es_95),
                   max_drawdown = sprintf("%.1f%%", 100 * max_drawdown),
                   skewness = sprintf("%.2f", skewness)) |>
  kable(align = "rlrrrr",
        col.names = c("window", "", "Sharpe", "ES 95%", "max drawdown", "skewness"))

## ---- oos-facts ----
# The orders the next two paragraphs state, asserted so that a rerun of the
# register which no longer supports them stops the render.
windows   <- sort(unique(oos$window))
es_excess <- vapply(windows, function(w)
  pick(w, "min_cvar", "es_95") - pick(w, "min_variance", "es_95"), numeric(1))
se_sharpe <- function(sr, n) sqrt((1 + (sr / sqrt(12))^2 / 2) / n) * sqrt(12)   # @eq-25-se, annualized
se_36     <- se_sharpe(pick(36, "min_cvar", "sharpe"), pick(36, "min_cvar", "n_periods"))
stopifnot(identical(windows, c(36L, 60L, 120L)),
          all(es_excess > 0),            # minimum ES realizes the higher shortfall at every window
          pick(60,  "min_cvar", "sharpe")   > pick(60,  "min_variance", "sharpe"),
          pick(60,  "min_cvar", "skewness") > pick(60,  "min_variance", "skewness"),
          pick(120, "min_cvar", "sharpe")   < pick(120, "min_variance", "sharpe"),
          pick(120, "min_cvar", "skewness") < pick(120, "min_variance", "skewness"),
          oos$sharpe[oos$window == 36 & oos$strategy == "min_cvar"] == max(oos$sharpe),
          diff(range(oos$sharpe)) < 1.96 * se_36)
